[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$JobRoot,[Parameter(Mandatory=$true)][string]$AttemptId,[string]$RepositoryRoot)
$ErrorActionPreference='Stop';if(-not$RepositoryRoot){$RepositoryRoot=Split-Path -Parent $PSScriptRoot};$attempt=Join-Path $JobRoot (Join-Path 'output' $AttemptId);if(Test-Path $attempt){throw "Attempt exists"};$src=Join-Path $RepositoryRoot 'src';$main=Join-Path $src 'fg_connected_tail_l84_l87\rtx_connected_l56_l87.cpp';$core=Join-Path $src 'fg_connected_tail_l84_l87\rtx_core_bridge.cpp';$modules=Join-Path $JobRoot 'inputs\modules';$model=Join-Path $JobRoot 'inputs\model';$cuda=$env:CUDA_PATH;if(-not$cuda){$cuda='C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$install=&$vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vcvars=Join-Path $install 'VC\Auxiliary\Build\vcvars64.bat';$build=Join-Path $attempt 'build';New-Item -ItemType Directory -Path $build|Out-Null;$o1=Join-Path $build 'main.obj';$o2=Join-Path $build 'core.obj';$exe=Join-Path $build 'connected-l56-l87.exe';$log=Join-Path $build 'compile.log';$cmd='"{0}" >nul && cl.exe /nologo /std:c++20 /EHsc /MD /W4 /WX /permissive- /Zc:__cplusplus /utf-8 /I"{1}" /Fo"{2}" /c "{3}" >"{4}" 2>&1 && cl.exe /nologo /std:c++20 /EHsc /MD /W4 /WX /permissive- /Zc:__cplusplus /utf-8 /I"{1}" /Fo"{5}" /c "{6}" >>"{4}" 2>&1 && link.exe /nologo /OUT:"{7}" "{2}" "{5}" "{8}" bcrypt.lib d3d12.lib dxgi.lib >>"{4}" 2>&1' -f $vcvars,(Join-Path $cuda 'include'),$o1,$main,$log,$o2,$core,$exe,(Join-Path $cuda 'lib\x64\cuda.lib');&$env:ComSpec /d /s /c $cmd;if($LASTEXITCODE-ne 0){throw "Build failed $log"}
$receipts=@();foreach($poison in @('a5','5a')){foreach($ord in @('a','b')){$id="connected-l56-l87-poison-$poison-process-$ord";$run=Join-Path $attempt $id;New-Item -ItemType Directory -Path $run|Out-Null;$p=Start-Process -FilePath $exe -ArgumentList @($modules,$model,$run,$id,$poison) -NoNewWindow -Wait -PassThru -RedirectStandardOutput (Join-Path $run 'stdout.log') -RedirectStandardError (Join-Path $run 'stderr.log');if($p.ExitCode-ne 0){throw "Run failed $id"};$receipts+=Get-Content (Join-Path $run 'run-receipt.json') -Raw|ConvertFrom-Json}}
$hashes=@($receipts|%{$_.final_output_sha256}|Sort-Object -Unique);$checks=@($receipts|%{($_.checkpoint_sha256|ConvertTo-Json -Compress)}|Sort-Object -Unique);$pids=@($receipts|%{$_.process_id}|Sort-Object -Unique);if($hashes.Count-ne 1-or$checks.Count-ne 1-or$pids.Count-ne 4){throw 'repeat gate'};$r=[ordered]@{schema='neuralstudio.fg.connected-l56-l87-rig.v1';job_id=(Split-Path -Leaf $JobRoot);attempt_id=$AttemptId;gpu=(&nvidia-smi --query-gpu=name,driver_version,memory.total --format=csv,noheader,nounits|Select-Object -First 1).Trim();cuda_toolkit=(&(Join-Path $cuda 'bin\nvcc.exe')--version|Select-Object -Last 1).Trim();source_sha256=(Get-FileHash $main -Algorithm SHA256).Hash.ToLowerInvariant();core_source_sha256=(Get-FileHash $core -Algorithm SHA256).Hash.ToLowerInvariant();binary_sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant();fresh_process_count=4;all_checkpoint_two_poison_invariant=$true;final_output_sha256=$hashes[0];address_fields_recorded=$false;result='pass'};$enc=New-Object Text.UTF8Encoding($false);$rp=Join-Path $attempt 'rig-receipt.json';[IO.File]::WriteAllText($rp,(($r|ConvertTo-Json -Depth 4)+"`n"),$enc);Write-Host "attempt_root=$attempt";Write-Host "output_sha256=$($hashes[0])";Write-Host result=pass
